package dev.deepseek.mobileimport androidx.compose.foundation.*import androidx.compose.foundation.layout.*import androidx.compose.material3.*import androidx.compose.runtime.*import androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.graphics.vector.ImageVectorimport androidx.compose.ui.platform.*import androidx.compose.ui.text.*import androidx.compose.ui.text.font.*import androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.sp/** 页面间复用的小按钮、入口行和任务状态文字。 */@Composableinternal fun SmallIcon(    icon: ImageVector,    label: String,    enabled: Boolean = true,    action: () -> Unit,) {    IconButton(onClick = action, enabled = enabled) {        Icon(icon, label, Modifier.size(22.dp), tint = if (enabled) WhaleInk else WhaleMuted)    }}@Composableinternal fun ActionRow(icon: ImageVector, title: String, detail: String, click: () -> Unit) {    Row(        Modifier.fillMaxWidth()            .padding(vertical = 5.dp)            .clip(ContinuousShape(16.dp))            .background(WhaleTint)            .clickable(onClick = click)            .padding(16.dp),        verticalAlignment = Alignment.CenterVertically,    ) {        Icon(icon, null, Modifier.size(22.dp), tint = WhaleBlue)        Column(Modifier.weight(1f).padding(start = 12.dp)) {            Text(title, fontSize = 14.sp, fontWeight = FontWeight.Medium)            Text(                detail,                fontSize = 11.sp,                color = WhaleMuted,                modifier = Modifier.padding(top = 5.dp),            )        }        Icon(AppIcons.ArrowOut, null, Modifier.size(18.dp), tint = WhaleMuted)    }}internal fun statusName(s: String) =    mapOf(        "queued" to "排队中",        "running" to "执行中",        "waiting" to "等待你确认",        "stopping" to "正在停止",        "done" to "已结束",        "failed" to "失败",        "cancelled" to "已取消",        "interrupted" to "已中断",    )[s] ?: s/** Consistent quick-selection rows, shared by centered islands. */@Composableinternal fun OptionRow(    icon: ImageVector,    title: String,    detail: String,    selected: Boolean,    tint: androidx.compose.ui.graphics.Color = WhaleBlue,    click: () -> Unit,) {    Row(        Modifier.fillMaxWidth()            .padding(vertical = 2.dp)            .clip(ContinuousShape(14.dp))            .background(if (selected) WhaleTint else androidx.compose.ui.graphics.Color.Transparent)            .clickable(onClick = click)            .padding(horizontal = 10.dp, vertical = 12.dp),        verticalAlignment = Alignment.CenterVertically,    ) {        Icon(icon, null, Modifier.size(22.dp), tint = tint)        Column(Modifier.weight(1f).padding(start = 12.dp)) {            Text(title, fontSize = 14.sp)            if (detail.isNotEmpty())                Text(                    detail,                    fontSize = 11.sp,                    color = WhaleMuted,                    modifier = Modifier.padding(top = 3.dp),                )        }        if (selected) Icon(AppIcons.Check, "已选择", Modifier.size(17.dp), tint = tint)    }}